-- C11 / P11.8 — immutable sales/royalties/returns/read-through metrics with projected/confirmed/settled separation.
create table if not exists public.command_center_book_performance_metric_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 metric_event_id text not null check(btrim(metric_event_id)<>''), metric_id text not null check(btrim(metric_id)<>''), project_id text not null check(btrim(project_id)<>''), book_id text not null check(btrim(book_id)<>''), format text not null check(btrim(format)<>''), metric text not null check(metric in ('sales','royalties','returns','read_through')), value numeric not null check(value>=0), currency text, truth text not null check(truth in ('projected','confirmed','settled')), period_start timestamptz not null, period_end timestamptz not null, observed_at timestamptz not null, source_refs text[] not null check(cardinality(source_refs)>0), provider_record_ref text not null check(btrim(provider_record_ref)<>''), settlement_ref text,
 primary key(owner_id,metric_event_id), unique(owner_id,metric_id), check(period_start<=period_end and period_end<=observed_at),
 check((metric='royalties' and currency is not null and btrim(currency)<>'') or (metric<>'royalties' and currency is null)),
 check((truth='settled' and metric='royalties' and settlement_ref is not null and btrim(settlement_ref)<>'') or (truth<>'settled' and settlement_ref is null) or (truth='settled' and metric<>'royalties' and settlement_ref is null))
);
create or replace view public.command_center_book_performance_metrics_current with (security_invoker=true) as select owner_id,metric_event_id,metric_id,project_id,book_id,format,metric,value,currency,truth,period_start,period_end,observed_at,source_refs,provider_record_ref,settlement_ref from public.command_center_book_performance_metric_history;
create or replace function public.command_center_reject_book_performance_evidence_mutation() returns trigger language plpgsql set search_path to 'public' as $$ begin raise exception 'Book performance evidence is immutable'; end $$;
drop trigger if exists command_center_book_performance_immutable on public.command_center_book_performance_metric_history; create trigger command_center_book_performance_immutable before update or delete on public.command_center_book_performance_metric_history for each row execute function public.command_center_reject_book_performance_evidence_mutation();
alter table public.command_center_book_performance_metric_history enable row level security;
revoke all on table public.command_center_book_performance_metric_history from public,anon,authenticated; grant select,insert on table public.command_center_book_performance_metric_history to authenticated; grant select on table public.command_center_book_performance_metrics_current to authenticated;
create policy p11_8_book_performance_owner on public.command_center_book_performance_metric_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
